    store.createCardInteraction({ id: "continue-1", bindingId: "b1", bindingGeneration: 1, actorOpenId: "creator", actionKind: "continuation", parentPromptId: "parent", targetPromptId: null, expiresAt: "2099-01-01T00:00:00.000Z" });
