      id: "worker-observed", projectId: "project-a", name: "worker", role: "worker", agentKind: "traex", model: null,
      desiredState: "running", parent: { bindingId: "binding-a", bindingGeneration: 1, paneId: "w1:primary", nativeSessionId: null },
