    store.database.exec("CREATE TEMP TRIGGER reject_second_queue_card BEFORE INSERT ON outbound_replies WHEN NEW.kind = 'card_update' AND NEW.prompt_id = 'p2' BEGIN SELECT RAISE(ABORT, 'reject second outbox'); END");

