    store.enqueueOutboundReply({ id: "failed-rebuild", idempotencyKey: "failed-rebuild", bindingId: "b1", promptId: "uncertain", cardRole: "answer", rootMessageId: "answer", kind: "card_update", payload: "{\"secret\":true}" });
